"src/astra251/health.mjs":(module,require)=>{
const {schema251,meter251}=require("src/astra251/schema.mjs");
const {ownerStatus251}=require("src/astra251/owner.mjs");
const yes=v=>v===true||v==='true';
async function commerceStatus251(env){
 try{const p=await env.DB.prepare('SELECT stars_enabled,payment_scope,support,terms_version,retention_days,verified_bot_id FROM astra_policy WHERE singleton=1').first();
  const scope=yes(env.ASTRA_TELEGRAM_TEST_MODE)?'test':'production',worker=yes(env.STARS_SHOP_ENABLED),db=p?.stars_enabled===1;
  const configured=Boolean(p&&p.payment_scope===scope&&p.support==='https://t.me/BAL1k_67'&&p.terms_version==='astra-stars-2026-11-v1'&&p.retention_days===365&&p.verified_bot_id===Number(String(env.ASTRA_BOT_TOKEN||'').split(':')[0]));
  const approved=env.ASTRA_PAYMENT_POLICY_ACCEPTED==='APPROVED_SUPPORT_TERMS_RETENTION'&&(scope==='test'?env.ASTRA_PAYMENT_ENVIRONMENT_ACK==='DEDICATED_TELEGRAM_TEST_ENVIRONMENT_CONFIRMED':env.ASTRA_STARS_LIVE_APPROVED==='YES_I_AUTHORIZE_REAL_STARS');
  return{configured,worker_enabled:worker,database_enabled:db,live_ready:Boolean(worker&&db&&configured&&approved),safe:Boolean(worker===db&&(!worker||configured&&approved))};
 }catch{return{configured:false,worker_enabled:yes(env.STARS_SHOP_ENABLED),database_enabled:false,live_ready:false,safe:!yes(env.STARS_SHOP_ENABLED)};}
}
async function health251(env,{base,tarot,registry,validateArt,forecastActive}){
 const state={...base,release_scope:'ASTRA_2_5_1'},blockers=[],require=(ok,code)=>{if(!ok)blockers.push(code);};
 state.full_schema_ready=await schema251(env);require(state.full_schema_ready,'FINAL_SCHEMA_MISMATCH');
 require(base.db_query==='OK','D1_UNAVAILABLE');require(base.secrets_ready,'BOT_SECRETS_MISSING');require(base.policy_ready,'POLICY_NOT_READY');require(base.bonus_fence_ready,base.bonus_fence_blocker||'BONUS_FENCE_NOT_READY');require(base.manual_content_ready,'MANUAL_CONTENT_NOT_READY');require(base.consent_schema_ready,'CONSENT_SCHEMA_NOT_READY');require(forecastActive,'FORECAST_NOT_ACTIVE');
 state.tarot25_schema_ready=tarot.ready===true;state.tarot25_sales_enabled=Boolean(tarot.ready&&tarot.enabled===1&&tarot.write_enabled===1&&tarot.independent_enabled===1&&yes(env.ASTRA_TAROT25_ENABLED)&&yes(env.ASTRA_TAROT25_STORAGE_TEST_MODE)&&yes(env.ASTRA_TAROT25_INDEPENDENT_TEST_MODE));require(state.tarot25_sales_enabled,'TAROT_SALES_DISABLED');
 try{validateArt(registry);state.art_registry_ready=registry.bot_id===Number(String(env.ASTRA_BOT_TOKEN||'').split(':')[0])&&registry.realm===(yes(env.ASTRA_TELEGRAM_TEST_MODE)?'test':'production');}catch{state.art_registry_ready=false;}
 state.art_enabled=yes(env.ASTRA_TAROT_ART_ENABLED);require(state.art_registry_ready,'ART_BOT_OR_REGISTRY_MISMATCH');require(state.art_enabled,'ART_DISABLED');
 try{const m=await meter251(env);state.storage_budget_ready=Math.max(m.size,m.logical+m.overhead)+65536<=tarot.soft_cap_bytes;}catch{state.storage_budget_ready=false;}require(state.storage_budget_ready,'DRAFT_STORAGE_META_OR_CAP_UNAVAILABLE');
 const owner=await ownerStatus251(env);state.admin_schema_ready=state.full_schema_ready;state.admin_ready=owner.ready;state.owner_enrollment_required=!owner.ready;
 if(owner.configured)require(owner.ready,'OWNER_BINDING_UNVERIFIED');
 const shop=await commerceStatus251(env);state.stars_configured=shop.configured;state.stars_ready=shop.live_ready;state.stars_shop_enabled=shop.worker_enabled&&shop.database_enabled;state.stars_configuration_ready=shop.safe;
 require(shop.safe,'STARS_GATES_OR_APPROVAL_MISMATCH');
 require(!yes(env.ASTRA_DAILY_DELIVERY_ENABLED)&&base.broadcast_delivery_allowed===false,'BROADCAST_MUST_REMAIN_OFF');require(!yes(env.ASTRA_TAROT25_QUESTIONS_TEST_MODE)&&tarot.questions_enabled===0,'QUESTIONS_MUST_REMAIN_OFF');
 state.blockers=[...new Set(blockers)];state.ready=state.blockers.length===0;state.public_ready=state.ready;state.readiness_scope='operational_checks_only';state.platform_metrics='NOT_ATTESTED_BY_HEALTH';
 return Response.json(state,{status:state.ready?200:503,headers:{'Cache-Control':'no-store'}});
}

async function paymentsReady251(env){return await schema251(env)&&(await commerceStatus251(env)).live_ready;}

Object.assign(module.exports,{commerceStatus251,health251,paymentsReady251});
},
"src/astra251/owner.mjs":(module,require)=>{
const {AUTH251,schema251}=require("src/astra251/schema.mjs");
const enc=new TextEncoder(),hex=b=>Array.from(new Uint8Array(b),n=>n.toString(16).padStart(2,'0')).join('');
const fail=code=>Object.assign(Error(code),{code});
const idOK=n=>Number.isSafeInteger(n)&&n>0&&n<2**52;
const equal=(a,b)=>{a=String(a??'');b=String(b??'');let n=a.length^b.length;for(let i=0;i<Math.max(a.length,b.length);i++)n|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0);return n===0;};
async function mac251(env,data){if(typeof env.ASTRA_BONUS_FENCE_KEY!=='string'||enc.encode(env.ASTRA_BONUS_FENCE_KEY).length<32)throw fail('OWNER_PROOF_KEY_MISSING');const k=await crypto.subtle.importKey('raw',enc.encode(env.ASTRA_BONUS_FENCE_KEY),{name:'HMAC',hash:'SHA-256'},false,['sign']);return hex(await crypto.subtle.sign('HMAC',k,enc.encode(JSON.stringify(data))));}
const ownerPayload251=c=>['astra251-owner-v1',c.bot_id,c.owner_id,c.owner_generation,c.build_sha256,c.parent_sha256,c.challenge_hash,c.claim_update,c.claim_message,c.claimed_at];
function scopeOK(env,c){return Boolean(c&&idOK(c.bot_id)&&c.bot_id===Number(String(env.ASTRA_BOT_TOKEN||'').split(':')[0])&&/^[a-f0-9]{64}$/.test(env.ASTRA_ADMIN_BUILD_SHA256||'')&&c.build_sha256===env.ASTRA_ADMIN_BUILD_SHA256);}
async function config(env){return env.DB.prepare('SELECT c.*,g.generation AS current_generation,unixepoch() AS db_now FROM astra_owner251 c LEFT JOIN astra_user_policy g ON g.telegram_id=c.owner_id WHERE singleton=1').first();}
async function ownerStatus251(env){
 try{const c=await config(env),configured=env.ASTRA_OWNER_TELEGRAM_ID!==undefined&&env.ASTRA_OWNER_TELEGRAM_ID!=='';
  const attested=Boolean(c?.state==='enrolled'&&idOK(c.owner_id)&&c.owner_generation===c.current_generation&&scopeOK(env,c)&&equal(c.proof_mac,await mac251(env,ownerPayload251(c))));
  const ready=attested&&String(c.owner_id)===String(env.ASTRA_OWNER_TELEGRAM_ID);
  return{ready,attested,configured,state:c?.state??'missing',config:c};
 }catch{return{ready:false,attested:false,configured:Boolean(env.ASTRA_OWNER_TELEGRAM_ID),state:'unavailable'};}
}
function privateMessage(m){return m?.chat?.type==='private'&&idOK(m.from?.id)&&m.chat.id===m.from.id&&m.from.is_bot===false&&!m.sender_chat&&!m.via_bot&&!m.forward_origin&&!m.forward_date&&!m.forward_from&&!m.forward_from_chat&&!m.is_automatic_forward&&Number.isSafeInteger(m.message_id)&&m.message_id>0&&Number.isSafeInteger(m.date)&&m.date>0;}
function proofText(c){const bytes=enc.encode(JSON.stringify(ownerPayload251(c)));const p=btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');return p+'.'+c.proof_mac;}
async function proofReply(env,id,c,send){await send(env,id,'Аккаунт подтверждён через личный чат с ботом. Административные начисления пока выключены.

Скопируйте эту строку только в локальную программу подтверждения владельца:
'+proofText(c)+'

Это приватное подтверждение: не публикуйте его в GitHub или общем чате.');}
async function adminMessage251(env,m,uid,{send:transport}){
 const send=async(...args)=>{try{return await transport(...args);}catch{throw fail('ADMIN_REPLY_UNKNOWN');}};
 const text=typeof m?.text==='string'?m.text.trim():'';
 if(!/^/(?:myid|admin|grant|owner_claim|owner_proof)(?:\s|$)/u.test(text))return false;
 if(env[AUTH251]!==true||!env.ASTRA_WEBHOOK_SECRET||!privateMessage(m)||!Number.isSafeInteger(uid)||uid<0)return true;
 const id=m.from.id;
 if(text==='/myid'){await send(env,id,'Ваш Telegram ID: '+id);return true;}
 try{
  if(!await schema251(env))throw fail('ADMIN_SCHEMA_NOT_READY');
  if(text.startsWith('/owner_claim ')){
   const token=text.slice(13);if(!/^[A-Za-z0-9_-]{43}$/.test(token))throw fail('OWNER_CHALLENGE_INVALID');
   let c=await config(env);if(!scopeOK(env,c))throw fail('OWNER_BUILD_MISMATCH');
   if(c.state==='enrolled'){
    if(c.owner_id!==id||c.owner_generation!==c.current_generation||!equal(c.proof_mac,await mac251(env,ownerPayload251(c))))throw fail('OWNER_ALREADY_ENROLLED');
    await proofReply(env,id,c,send);return true;
   }
   const hash=hex(await crypto.subtle.digest('SHA-256',enc.encode(token)));
   if(c.state!=='pending'||!equal(hash,c.challenge_hash)||c.expires_at<=c.db_now||m.date<c.db_now-300||m.date>c.db_now+30)throw fail('OWNER_CHALLENGE_INVALID');
   const p=await env.DB.prepare('SELECT p.generation FROM astra_users u JOIN astra_user_policy p USING(telegram_id)WHERE u.telegram_id=? AND u.zodiac IS NOT NULL').bind(id).first();if(!p)throw fail('OWNER_PROFILE_REQUIRED');
   const proposed={...c,owner_id:id,owner_generation:p.generation,claim_update:uid,claim_message:m.message_id,claimed_at:c.db_now};proposed.proof_mac=await mac251(env,ownerPayload251(proposed));
   await env.DB.prepare("UPDATE astra_owner251 SET state='enrolled',owner_id=?,owner_generation=?,claim_update=?,claim_message=?,claimed_at=?,proof_mac=? WHERE singleton=1 AND state='pending' AND challenge_hash=? AND expires_at>unixepoch() AND owner_id IS NULL").bind(id,p.generation,uid,m.message_id,c.db_now,proposed.proof_mac,hash).run();
   c=await config(env);if(c.owner_id!==id||c.owner_generation!==p.generation||!equal(c.proof_mac,await mac251(env,ownerPayload251(c))))throw fail('OWNER_CLAIM_UNCONFIRMED');await proofReply(env,id,c,send);return true;
  }
  const owner=await ownerStatus251(env);
  if(text==='/owner_proof'&&owner.attested&&owner.config.owner_id===id){await proofReply(env,id,owner.config,send);return true;}
  if(!owner.ready||owner.config.owner_id!==id)throw fail('ADMIN_NOT_AUTHORIZED');
  if(text==='/admin'){await send(env,id,'Астра · Управление

/grant ID СУММА — начислить 1–1000 ✨ зарегистрированному пользователю или себе.
/myid — ваш Telegram ID.

Начисления записываются в журнал. Долг по возвратам погашается первым. Настоящие Telegram Stars эта команда не создаёт.');return true;}
  const match=/^/grant ([1-9][0-9]{0,15}) ([1-9][0-9]{0,3})$/.exec(text);if(!match)throw fail('ADMIN_COMMAND_FORMAT');
  const target=Number(match[1]),amount=Number(match[2]);if(!idOK(target)||!Number.isInteger(amount)||amount>1000)throw fail('ADMIN_COMMAND_FORMAT');
  const old=await env.DB.prepare('SELECT * FROM astra_admin_grants25 WHERE update_id=?').bind(uid).first();
  const targetRow=old?{generation:old.target_generation}:await env.DB.prepare('SELECT g.generation FROM astra_users u JOIN astra_user_policy g USING(telegram_id)WHERE u.telegram_id=? AND u.zodiac IS NOT NULL').bind(target).first();
